import {reviewedOn,mapGroups,modules,frontiers,cases,sources,connections,foundations,learningRoutes} from './course-map-data.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const moduleById=new Map(modules.map(m=>[m.id,m])),frontierById=new Map(frontiers.map(r=>[r.id,r])),caseById=new Map(cases.map(c=>[c.id,c]));
const state={view:'map',selected:'avl',lens:'question',query:'',group:'all',status:'all',zoom:100,collapsed:new Set()};
const labels={question:'关键问题',challenge:'挑战与难点',application:'应用案例',research:'研究前沿'};
const site='https://stan-haochen.github.io/ads-knowledge-site/';
let chapterData=[],demoData={};
const chapter=id=>chapterData.find(c=>c.id===id);
const title=id=>chapter(id)?.title||id;
const refLinks=refs=>refs.length?`<div class="map-refs">${refs.map(id=>{const r=sources[id];return `<a href="${esc(r.url)}" target="_blank" rel="noopener">${esc(r.title)} ↗<small>${esc(r.type)} · ${esc(r.date)}</small></a>`}).join('')}</div>`:'';
const chapterLinks=ids=>ids.map(id=>`<a href="#${id}" class="map-chip">${esc(title(id))} ↗</a>`).join('');
const brief=(m,lens)=>lens==='challenge'?m.challenge:lens==='application'?m.apps.map(id=>caseById.get(id).title).join(' / '):lens==='research'?m.research.map(id=>frontierById.get(id).title).join(' / '):m.question;
function wrap(s,limit=17,rows=2){const chars=[...s],out=[];while(chars.length&&out.length<rows)out.push(chars.splice(0,limit).join(''));if(out.length===2&&/^[？。，；！]$/.test(out[1])){out[1]=out[0].slice(-1)+out[1];out[0]=out[0].slice(0,-1)}if(chars.length)out[out.length-1]=out.at(-1).slice(0,-1)+'…';return out}
export function matchingModules(query='',group='all'){
 const q=query.trim().toLocaleLowerCase(),allowed=mapGroups.find(g=>g.id===group)?.ids;
 return modules.filter(m=>(!allowed||allowed.includes(m.id))&&(!q||JSON.stringify([m,chapter(m.id)?.title,m.research.map(id=>frontierById.get(id)),m.apps.map(id=>caseById.get(id))]).toLocaleLowerCase().includes(q)));
}
export function mapSVG(chapters,{lens='question',selected='',matches=modules.map(m=>m.id),collapsed=new Set(),standalone=false}={}){
 const getTitle=id=>chapters.find(c=>c.id===id)?.title||id,nums=new Map(chapters.map(c=>[c.id,c.n]));
 const count=Math.max(1,...mapGroups.map(g=>collapsed.has(g.id)?0:g.ids.length)),h=300+count*100;
 let body=`<title>ADS 完整课程知识地图</title><desc>四条主线，十五个专题。当前视角：${labels[lens]}。研究状态核查日期 ${reviewedOn}。</desc><rect width="1160" height="${h}" fill="#f7f9f4"/><text x="580" y="30" text-anchor="middle" fill="#667567" font-size="13">ADS · ${labels[lens]} · 核查 ${reviewedOn}</text><rect x="405" y="50" width="350" height="84" rx="12" fill="#203830"/><text x="580" y="84" text-anchor="middle" fill="#fff" font-size="23" font-weight="600">高级数据结构与算法分析</text><text x="580" y="110" text-anchor="middle" fill="#d8e9c8" font-size="14">建模 → 设计 → 证明 → 成本 → 边界</text>`;
 mapGroups.forEach((g,i)=>{const x=155+i*282,hide=collapsed.has(g.id),groupHasMatch=g.ids.some(id=>matches.includes(id));
  body+=`<path d="M580 134 V155 H${x} V178" fill="none" stroke="${g.color}" stroke-width="2" opacity=".6"/><g ${standalone?'':`role="button" tabindex="0" data-collapse="${g.id}" aria-expanded="${!hide}" aria-label="${hide?'展开':'折叠'}${g.title}"`} class="map-group"><rect x="${x-124}" y="178" width="248" height="75" rx="8" fill="${g.color}" opacity="${groupHasMatch?1:.45}"/><text x="${x}" y="207" text-anchor="middle" fill="white" font-size="18" font-weight="600">${esc(g.title)}</text><text x="${x}" y="233" text-anchor="middle" fill="white" font-size="12">${esc(hide?'＋ 已折叠 · '+g.ids.length+' 个专题':g.question)}</text></g>`;
  if(!hide)g.ids.forEach((id,j)=>{const m=moduleById.get(id),y=281+j*100,active=id===selected,hit=matches.includes(id),lines=wrap(brief(m,lens));body+=`<path d="M${x} 253 H${x-133} V${y+39} H${x-119}" fill="none" stroke="${g.color}" stroke-width="1.5" opacity=".35"/><g ${standalone?'':`role="button" tabindex="0" data-map-node="${id}" aria-label="${esc(getTitle(id))}：${esc(brief(m,lens))}" aria-pressed="${active}"`} class="map-node" opacity="${hit?1:.26}"><title>${esc(getTitle(id))}：${esc(brief(m,lens))}</title><rect x="${x-119}" y="${y}" width="238" height="81" rx="8" fill="${active?'#e7f2d7':'white'}" stroke="${active?'#537e30':g.color}" stroke-width="${active?2.5:1}"/><text x="${x-105}" y="${y+26}" font-size="15" font-weight="600" fill="#203830">${nums.get(id)} · ${esc(getTitle(id))}</text>${lines.map((line,k)=>`<text x="${x-105}" y="${y+48+k*17}" font-size="12" fill="#5b685d">${esc(line)}</text>`).join('')}</g>`});
 });
 body+=`<text x="28" y="${h-12}" font-size="12" fill="#627162">实线表示课程归属；跨章联系见单独视图。课件 16 份 / 285 页，ADS00 为导论。</text>`;
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1160 ${h}" ${standalone?'width="1160" height="'+h+'"':'class="course-map-svg"'} style="font-family:Microsoft YaHei,system-ui,sans-serif" role="group" aria-label="课程思维导图">${body}</svg>`;
}
function researchCard(r,compact=false){return `<article class="research-card" id="research-${r.id}"><div class="research-label ${r.kind}">${esc(r.label)}<span>核查 ${reviewedOn}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.question)}</p><dl><dt>已知结果与进展</dt><dd>${esc(r.known)}</dd><dt>${r.kind==='milestone'?'状态边界':'尚需解决 / 适用边界'}</dt><dd>${esc(r.remaining)}</dd>${compact?'':`<dt>从课内走向研究</dt><dd>${esc(r.bridge)}</dd><dt>可开展的学习任务</dt><dd>${esc(r.entry)}</dd>`}</dl><div class="map-chips">${chapterLinks(r.modules)}</div>${refLinks(r.refs)}</article>`}
function caseCard(c){return `<article class="case-card"><span class="map-tag">${esc(c.type)}</span><h3>${esc(c.title)}</h3><ol class="case-flow">${c.flow.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><p>${esc(c.detail)}</p><div class="case-metric"><b>如何评价</b><p>${esc(c.metrics)}</p></div><div class="map-chips">${chapterLinks(c.modules)}</div>${refLinks(c.refs)}</article>`}
function moduleDetail(m,{full=false}={}){const c=chapter(m.id);return `<article class="module-detail" id="module-${m.id}"><div class="module-header"><div><span class="map-tag">CHAPTER ${c.n} / ${esc(c.group)}</span><h2>${esc(c.title)}</h2><p>${esc(m.question)}</p></div><a class="map-lesson-link" href="#${m.id}">进入本章讲义 ↗</a></div><div class="module-source">课件依据：${esc(c.file)} · p.${esc(c.pages)}　|　${esc(c.prereq)}</div><div class="map-chips">${m.topics.map(s=>`<span class="map-chip">${esc(s)}</span>`).join('')}</div><div class="module-columns"><section><h3>必须回答的关键问题</h3><ol>${m.questions.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><h3>证明与分析方法</h3><p>${esc(m.method)}</p><h3>复杂度与模型前提</h3><p>${esc(m.cost)}</p></section><section class="module-challenge"><span class="map-tag">CHALLENGE</span><h3>最有挑战的知识点</h3><p>${esc(m.challenge)}</p><h3>学到什么程度算掌握？</h3><p>${esc(m.check)}</p></section></div><h3>对应实验</h3><div class="map-chips">${c.demos.map(id=>`<a class="map-chip" href="#${c.id}/${id}">${esc(demoData[id]?.title||id)} ↗</a>`).join('')}</div><div class="module-columns"><section><h3>代表性应用</h3>${m.apps.map(id=>{const a=caseById.get(id);return `<div class="map-mini"><a href="#mindmap/cases" data-case-focus="${id}">${esc(a.title)} ↗</a><small>${esc(a.type)}</small><p>${esc(a.detail)}</p></div>`}).join('')}</section><section><h3>相关研究前沿</h3>${m.research.map(id=>{const r=frontierById.get(id);return `<div class="map-mini"><span class="research-label ${r.kind}">${esc(r.label)}</span><a href="#mindmap/research" data-research-focus="${id}">${esc(r.title)} ↗</a><p>${esc(r.bridge)}</p></div>`}).join('')}</section></div>${full?'':`<details><summary>本章与其他模块怎样联系？</summary>${connections.filter(([a,b])=>a===m.id||b===m.id).map(([a,b,kind,why])=>`<p><a href="#mindmap/${a===m.id?b:a}">${esc(title(a===m.id?b:a))}</a> · ${esc(kind)}<br>${esc(why)}</p>`).join('')}</details>`}</article>`}
function commonIntro(){return `<div class="map-boundary"><b>阅读约定</b><p>课程划分和学习任务是依据 Student Slides 的教学综合；研究条目来自所列论文及官方资料，状态核查截至 ${reviewedOn}。区分经典开放问题、条件性假设、工程研究议题与已突破的历史障碍。近期预印本按作者报告标注，本页不是穷尽性文献综述，也不把检索到论文等同于独立验证其全部证明。</p></div>`}
function renderContent(){const target=document.querySelector('#map-content'),matches=matchingModules(state.query,state.group);document.querySelector('#map-results').textContent=`${matches.length} / 15 个专题匹配`;
 if(state.view==='map'){
  if(matches.length&&!matches.some(m=>m.id===state.selected))state.selected=matches[0].id;
  target.innerHTML=`<div class="map-controls"><label>脑图视角 <select id="map-lens">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${k===state.lens?'selected':''}>${v}</option>`).join('')}</select></label><label>缩放 <input type="range" id="map-zoom" min="65" max="150" value="${state.zoom}" aria-label="脑图缩放"><output id="map-zoom-value">${state.zoom}%</output></label><button id="map-expand">展开全部</button><button id="map-detail-jump" class="map-detail-jump">阅读选中专题 ↓</button></div><p class="map-help">点击专题查看完整分析；点击主线标题折叠。灰色节点不符合筛选，可点击切换。窄屏可在画布内横向滑动，或切换“完整纲要”。</p><div class="map-canvas" tabindex="0" aria-label="可滚动课程脑图">${mapSVG(chapterData,{lens:state.lens,selected:state.selected,matches:matches.map(m=>m.id),collapsed:state.collapsed})}</div><section id="map-selected">${matches.length?moduleDetail(moduleById.get(state.selected)):'<div class="map-empty">没有匹配的专题。尝试“势能”“I/O”“PIT”或清空筛选。</div>'}</section>`;
  const svg=target.querySelector('svg');svg.style.width=state.zoom+'%';svg.style.minWidth=8.6*state.zoom+'px';
  target.querySelector('#map-lens').onchange=e=>{state.lens=e.target.value;renderContent()};
  target.querySelector('#map-zoom').oninput=e=>{state.zoom=+e.target.value;svg.style.width=state.zoom+'%';svg.style.minWidth=8.6*state.zoom+'px';target.querySelector('#map-zoom-value').textContent=state.zoom+'%'};
  target.querySelector('#map-expand').onclick=()=>{state.collapsed.clear();renderContent()};
 }else if(state.view==='outline')target.innerHTML=`<p class="map-help">完整纲要保留每章的关键问题、难点、证明方法、掌握标准和应用 / 研究入口。可使用上方搜索筛选。</p>${matches.map(m=>moduleDetail(m,{full:true})).join('')||'<div class="map-empty">没有匹配的专题。</div>'}`;
 else if(state.view==='research'){
  const ids=new Set(matches.flatMap(m=>m.research)),rs=frontiers.filter(r=>ids.has(r.id)&&(state.status==='all'||r.kind===state.status));
  target.innerHTML=commonIntro()+`<div class="research-filters" aria-label="研究状态筛选">${[['all','全部'],['open','开放问题'],['conditional','条件性假设'],['direction','研究方向'],['milestone','已突破障碍']].map(([id,label])=>`<button data-research-status="${id}" aria-pressed="${state.status===id}">${label}</button>`).join('')}</div><p class="map-help">当前显示 ${rs.length} 个研究条目。比较“目前能做什么”与“仍需证明什么”，再从入门任务向论文推进。</p><div class="map-card-grid">${rs.map(r=>researchCard(r)).join('')||'<div class="map-empty">该筛选下没有研究条目。</div>'}</div>`;
 }else if(state.view==='cases'){
  const ids=new Set(matches.flatMap(m=>m.apps));target.innerHTML=`<p class="map-help">区分真实产品 / 论文机制与教学建模。应用场景不等于某产品实际采用了课内全部算法。</p><div class="map-card-grid">${cases.filter(c=>ids.has(c.id)).map(c=>`<div id="case-${c.id}">${caseCard(c)}</div>`).join('')||'<div class="map-empty">没有匹配的案例。</div>'}</div>`;
 }else{
  const ids=new Set(matches.map(m=>m.id));target.innerHTML=`<h2>把知识点连接成解题能力</h2><div class="foundation-grid">${foundations.map(([a,b])=>`<article><h3>${a}</h3><p>${b}</p></article>`).join('')}</div><h2>三条建议学习路线</h2>${learningRoutes.map(r=>`<article class="learning-route"><h3>${r.title}</h3><div class="map-chips">${r.ids.map(id=>`<a href="#mindmap/${id}" class="map-chip">${esc(title(id))}</a>`).join('<span>→</span>')}</div><p>${r.goal}</p></article>`).join('')}<h2>跨章关系：箭头表示联系方向，不都表示严格先修</h2><div class="map-relations">${connections.filter(([a,b])=>ids.has(a)||ids.has(b)).map(([a,b,kind,why])=>`<article><span class="map-tag">${kind}</span><h3><a href="#mindmap/${a}">${esc(title(a))}</a> → <a href="#mindmap/${b}">${esc(title(b))}</a></h3><p>${esc(why)}</p></article>`).join('')}</div>`;
 }
}
const save=(filename,mime,text)=>{const url=URL.createObjectURL(new Blob([text],{type:mime})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
export function mapMarkdown(chapters){
 const name=id=>chapters.find(c=>c.id===id)?.title||id,refText=refs=>refs.map(id=>`- [${sources[id].title}](${sources[id].url}) · ${sources[id].type} · ${sources[id].date}`).join('\n');
 let s=`# ADS 完整课程知识地图\n\n研究状态核查：${reviewedOn}。来源：16 份 Student Slides，285 页；ADS00 为导论，15 个专题覆盖 ADS01–15。\n\n网站：${site}#mindmap\n\n课程综合与学习任务由本网站编写。近期研究以所列来源及版本为准，预印本不等同已完成同行评审；“研究方向”不是单一数学猜想。\n\n## 共同基础\n\n${foundations.map(([a,b])=>`- **${a}**：${b}`).join('\n')}\n`;
 for(const g of mapGroups){s+=`\n## ${g.title}\n\n${g.question}\n`;for(const id of g.ids){const m=moduleById.get(id),c=chapters.find(c=>c.id===id);s+=`\n### ${c.n} ${c.title}\n\n课件：${c.file}，p.${c.pages}。先修：${c.prereq}。\n\n[本章讲义](${site}#${id})\n\n**核心问题**：${m.question}\n\n**内容范围**：${m.topics.join('；')}\n\n${m.questions.map(q=>'- '+q).join('\n')}\n\n**挑战**：${m.challenge}\n\n**证明方法**：${m.method}\n\n**掌握标准**：${m.check}\n\n**成本模型**：${m.cost}\n\n**应用**：${m.apps.map(id=>caseById.get(id).title).join('；')}\n\n**研究延伸**：${m.research.map(id=>frontierById.get(id).title).join('；')}\n`}}
 s+=`\n## 跨章联系\n\n${connections.map(([a,b,k,w])=>`- ${name(a)} → ${name(b)}｜${k}：${w}`).join('\n')}\n\n## 建议学习路线\n\n${learningRoutes.map(r=>`### ${r.title}\n\n${r.ids.map(name).join(' → ')}\n\n${r.goal}`).join('\n\n')}\n\n## 开放问题与研究前沿\n`;
 for(const r of frontiers)s+=`\n### ${r.title}\n\n**${r.label}**｜核查 ${reviewedOn}\n\n${r.question}\n\n**已知进展**：${r.known}\n\n**边界 / 未解决部分**：${r.remaining}\n\n**课程衔接**：${r.bridge}\n\n**入门任务**：${r.entry}\n\n${refText(r.refs)}\n`;
 s+='\n## 代表性应用案例\n';for(const c of cases)s+=`\n### ${c.title}\n\n类型：${c.type}\n\n${c.flow.join(' → ')}\n\n${c.detail}\n\n评价指标：${c.metrics}\n\n相关章节：${c.modules.map(name).join('、')}\n\n${refText(c.refs)}\n`;
 return s;
}
let focusResearch='',focusCase='';
export function mountCourseMap(chapters,demos,requested){
 chapterData=chapters;demoData=demos;
 if(moduleById.has(requested)){state.selected=requested;state.view='map';state.query='';state.group='all';state.collapsed.clear()}
 else if(['map','outline','research','cases','connections'].includes(requested))state.view=requested;
 else state.view='map';
 document.title='完整课程知识地图 · ADS 算法研习室';document.querySelector('#breadcrumb').textContent='完整课程知识地图';document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.remove('active'));document.querySelector('[data-course-map]')?.classList.add('active');
 document.querySelector('#main').innerHTML=`<div class="eyebrow">CURRICULUM ATLAS / 全课程知识体系</div><h1>课程知识地图<span class="english">See the connections. Ask the next question.</span></h1><p class="intro">以四条主线串起 15 个专题，把关键问题、证明难点、代表性应用与研究边界放在同一张地图中。先建立全局坐标，再进入每章讲义与实验。</p><div class="map-meta"><span>16 份课件 · 285 页 · ADS00 为导论</span><span>研究核查 ${reviewedOn}</span><span>${frontiers.length} 个研究条目 · ${cases.length} 个应用案例</span></div><div class="map-toolbar"><label>搜索知识、难点或研究问题<input type="search" id="map-search" placeholder="例如：势能、I/O、PIT、GPU" value="${esc(state.query)}"></label><label>课程主线<select id="map-group"><option value="all">全部主线</option>${mapGroups.map(g=>`<option value="${g.id}" ${g.id===state.group?'selected':''}>${g.title}</option>`).join('')}</select></label><button id="map-clear">清空筛选</button><span id="map-results" role="status" aria-live="polite"></span></div><nav class="map-views" aria-label="知识地图视图">${[['map','总览脑图'],['outline','完整纲要'],['connections','跨章联系'],['research','开放问题与前沿'],['cases','应用案例']].map(([id,label])=>`<a href="#mindmap/${id}" ${id===state.view?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="map-export"><button id="map-svg-export">下载完整脑图 SVG</button><button id="map-md-export">下载完整知识地图 Markdown</button><span>导出包含全课程，不受当前搜索或折叠影响。</span></div><div id="map-content"></div><p class="map-footer">课程主干对照各章课件页码；本地图补充的应用、学习任务与研究延伸不是原课件逐字内容。研究状态不会自动联网更新，需随文献进展重新核查。</p>`;
 const input=document.querySelector('#map-search');input.oninput=()=>{state.query=input.value;renderContent()};document.querySelector('#map-group').onchange=e=>{state.group=e.target.value;renderContent()};document.querySelector('#map-clear').onclick=()=>{state.query='';state.group='all';state.status='all';input.value='';document.querySelector('#map-group').value='all';renderContent()};
 document.querySelector('#map-svg-export').onclick=()=>save('ADS-course-mindmap.svg','image/svg+xml;charset=utf-8',mapSVG(chapters,{lens:state.lens,standalone:true}));document.querySelector('#map-md-export').onclick=()=>save('ADS-course-knowledge-map.md','text/markdown;charset=utf-8',mapMarkdown(chapters));
 const content=document.querySelector('#map-content');content.onclick=e=>{if(e.target.closest('#map-detail-jump'))document.querySelector('#map-selected')?.scrollIntoView({block:'start'});const node=e.target.closest('[data-map-node]'),group=e.target.closest('[data-collapse]'),status=e.target.closest('[data-research-status]'),rf=e.target.closest('[data-research-focus]'),cf=e.target.closest('[data-case-focus]');if(node){state.selected=node.dataset.mapNode;state.group='all';state.query='';input.value='';document.querySelector('#map-group').value='all';history.replaceState(null,'','#mindmap/'+state.selected);renderContent()}if(group){const id=group.dataset.collapse;state.collapsed.has(id)?state.collapsed.delete(id):state.collapsed.add(id);renderContent()}if(status){state.status=status.dataset.researchStatus;renderContent()}if(rf){focusResearch=rf.dataset.researchFocus;state.status='all';state.query='';state.group='all'}if(cf){focusCase=cf.dataset.caseFocus;state.query='';state.group='all'}};
 content.onkeydown=e=>{const node=e.target.closest('[data-map-node],[data-collapse]');if(node&&['Enter',' '].includes(e.key)){e.preventDefault();const key=node.dataset.mapNode,grp=node.dataset.collapse;node.dispatchEvent(new MouseEvent('click',{bubbles:true}));content.querySelector(key?`[data-map-node="${key}"]`:`[data-collapse="${grp}"]`)?.focus()}};
 renderContent();
 if(state.view==='research'&&focusResearch){const id=focusResearch;focusResearch='';requestAnimationFrame(()=>document.querySelector('#research-'+id)?.scrollIntoView({block:'start'}))}if(state.view==='cases'&&focusCase){const id=focusCase;focusCase='';requestAnimationFrame(()=>document.querySelector('#case-'+id)?.scrollIntoView({block:'start'}))}
}
